import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`task-automator`,heroTitle:`Automate your tasks in minutes`,heroSubtitle:`Perplexity Computer turns a workflow link into a ready-to-run automation plan with tasks, tools, and follow-up steps mapped end to end.`,inputUrlCta:`Automate this task`,inputUrlPlaceholder:`e.g. notion.so/your-workflow`,inputUrlPrefill:`Go to {url} and analyze the workflow, source material, tools, and recurring steps. Then design an automation that can handle the task from intake to final output. Deliver: 1) A summary of the workflow and its inputs. 2) A task breakdown with triggers, decision points, and required tools. 3) A step-by-step automation plan with owners and outputs. 4) Draft messages, checklists, or handoff docs needed to run it. 5) A prioritized list of risks, approvals, and manual review points.`,heroOverlaySteps:[`Analyzing the workflow, source material, tools, and recurring steps`,`Mapping triggers, decision points, and handoffs across the task`,`Designing an automation plan with checks, outputs, and review points`,`Workflow plan, checklists, and handoff docs ready to run`],generatingSteps:[`Visiting {url} to understand the workflow, inputs, and current process`,`Designing an agent to break the task into reliable automation steps`,`Configuring tool handoffs, review checkpoints, and output formatting`,`Packaging the automation plan, checklist, and launch notes`],featureSectionTitle:`From recurring work to automated execution`,featureCardTitles:[`Connects to your operations stack`,`Outputs you can run`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, Sheets, Slack, Notion, Gmail, and project tools can feed one workflow so task automation is built around the tools you already use.`,`Task maps. Automation plans. Review checkpoints. Draft messages and checklists. Computer gives you a workflow that is ready to hand off or execute.`],capabilitySectionTitle:`Your task automation planner, on demand`,capabilitySectionSubtitle:`Drop in a workflow link, step away, and come back to a task automation plan.`,capabilityCards:[{title:`Workflow Analysis`,description:`Computer can inspect your process, inputs, outputs, and recurring steps so the automation starts from how the work actually happens.`},{title:`Task Breakdown`,description:`Computer can split the work into triggers, decisions, tool actions, and review points so every step has a clear purpose.`},{title:`Automation Plan`,description:`Computer can produce a sequenced plan with handoffs, checklists, messages, and outputs that make the workflow easier to run.`},{title:`Connect Your Tools`,description:`Computer can organize work across Docs, Sheets, Slack, Notion, Gmail, and project tools without forcing you into a new system.`},{title:`Remember Your Process`,description:`Computer can remember preferred formats, approval rules, and recurring task patterns so future automations fit your team.`},{title:`Monitor Follow-Ups`,description:`Computer can track open questions, missing inputs, and follow-up tasks so the workflow keeps moving after the first draft.`}]});export{t as default};
